using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using TMPro;using LWS.TruckSports;using LWS.TruckSports.Editor;
namespace LWS.TruckDerby.Editor {
public static class DerbyGoddessAuthoring {
 public static void Upgrade(){var scene=EditorSceneManager.OpenScene(DerbyAuthoring.Scene);Install(UnityEngine.Object.FindAnyObjectByType<DerbyMatch>());EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();}
 public static void Install(DerbyMatch match){var original=AssetDatabase.LoadAssetAtPath<Material>("Assets/TruckDemolitionDerby/Materials/Rutted floodlit stadium dirt.mat");const string path="Assets/TruckDemolitionDerby/Materials/Visible textured raised roll banks.mat";var paint=AssetDatabase.LoadAssetAtPath<Material>(path);if(paint==null){paint=new Material(original);paint.name="Visible textured raised roll banks";paint.SetColor("_BaseColor",new Color(.62f,.36f,.16f));paint.SetColor("_Color",new Color(.62f,.36f,.16f));paint.SetTextureScale("_BaseMap",new Vector2(2,4));AssetDatabase.CreateAsset(paint,path);}foreach(var renderer in UnityEngine.Object.FindObjectsByType<MeshRenderer>().Where(r=>r.name.StartsWith("EasyRoads physical surface")&&r.transform.root.name.StartsWith("Broad driveable roll bank")))renderer.sharedMaterials=Enumerable.Repeat(paint,renderer.sharedMaterials.Length).ToArray();foreach(var title in UnityEngine.Object.FindObjectsByType<TextMeshPro>().Where(t=>t.name=="Event screen readable rules")){title.text="TRUCK SPORTS: PARTY!\nDEMOLITION DERBY";EditorUtility.SetDirty(title);}for(int i=0;i<match.fighters.Length;i++){var t=match.fighters[i].transform;var forward=Vector3.ProjectOnPlane(t.position,Vector3.up);if(forward.sqrMagnitude>.1f){t.rotation=Quaternion.LookRotation(forward);EditorUtility.SetDirty(t);}}Shoulders(match,paint);EditorUtility.SetDirty(match);}
 // The vendor road ribbon is a sound longitudinal ramp, but its exposed sides
 // have no terrain underneath in this stadium. Add matching rendered/collider
 // shoulders over its actual saved heights, rather than changing NWH impacts.
 static void Shoulders(DerbyMatch match,Material paint){
  var banks=UnityEngine.Object.FindObjectsByType<MeshCollider>().Where(c=>c.name.StartsWith("EasyRoads physical surface")&&c.transform.root.name.StartsWith("Broad driveable roll bank")).OrderBy(c=>c.bounds.center.x).ToArray();
  Physics.SyncTransforms();int bankIndex=0;foreach(var bank in banks){for(int side=-1;side<=1;side+=2){string name="Continuous driveable bank shoulder "+side;if(bank.transform.parent.Find(name)!=null)continue;const int rows=113,columns=29;var vertices=new Vector3[rows*columns];var uv=new Vector2[vertices.Length];var triangles=new int[(rows-1)*(columns-1)*6];var bounds=bank.bounds;float edge=side<0?bounds.min.x:bounds.max.x;for(int row=0;row<rows;row++){float z=Mathf.Lerp(bounds.min.z+.002f,bounds.max.z-.002f,row/(float)(rows-1));float inside=edge-side*.025f;if(!bank.Raycast(new Ray(new Vector3(inside,bounds.max.y+10,z),Vector3.down),out var hit,30))throw new InvalidOperationException("Cannot sample actual saved EasyRoads bank shoulder: "+bank.name+" z="+z);float height=Mathf.Max(0,hit.point.y);for(int col=0;col<columns;col++){float t=col/(float)(columns-1);float x=edge+side*7*t;float y=height*(1-Mathf.SmoothStep(0,1,t));int index=row*columns+col;vertices[index]=new Vector3(x,y,z);uv[index]=new Vector2(x*.2f,z*.2f);}}
  int at=0;for(int row=0;row<rows-1;row++)for(int col=0;col<columns-1;col++){int a=row*columns+col,b=a+columns;int[] face=side>0?new[]{a,b,a+1,b,b+1,a+1}:new[]{a,a+1,b,b,a+1,b+1};foreach(int v in face)triangles[at++]=v;}
  string path="Assets/TruckDemolitionDerby/Models/Actual bank "+bankIndex+" shoulder "+side+".asset";var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(mesh==null){mesh=new Mesh();mesh.name="Smooth actual-road shoulder";AssetDatabase.CreateAsset(mesh,path);}mesh.Clear();mesh.vertices=vertices;mesh.uv=uv;mesh.triangles=triangles;mesh.RecalculateNormals();mesh.RecalculateBounds();EditorUtility.SetDirty(mesh);var go=new GameObject(name);go.transform.SetParent(bank.transform.parent,false);go.AddComponent<MeshFilter>().sharedMesh=mesh;go.AddComponent<MeshRenderer>().sharedMaterial=paint;var collider=go.AddComponent<MeshCollider>();collider.sharedMesh=mesh;collider.sharedMaterial=bank.sharedMaterial;
  }bankIndex++;}
  Physics.SyncTransforms();for(int i=0;i<match.props.movable.Length;i++){var body=match.props.movable[i];var p=match.props.positions[i];float y=0;foreach(var bank in banks)if(bank.Raycast(new Ray(new Vector3(p.x,10,p.z),Vector3.down),out var hit,20))y=Mathf.Max(y,hit.point.y);foreach(var shoulder in UnityEngine.Object.FindObjectsByType<MeshCollider>().Where(c=>c.name.StartsWith("Continuous driveable bank shoulder")))if(shoulder.Raycast(new Ray(new Vector3(p.x,10,p.z),Vector3.down),out var hit,20))y=Mathf.Max(y,hit.point.y);p.y=y+.025f;body.position=p;body.transform.position=p;match.props.positions[i]=p;EditorUtility.SetDirty(body.transform);}EditorUtility.SetDirty(match.props);
 }
 public static void DamageFixtures(){foreach(DerbyZone zone in Enum.GetValues(typeof(DerbyZone))){var baseline=new DerbyDamageState();var updated=new DerbyDamageState();float raw=.12f;baseline.Apply(zone,DerbyDamageState.ScaleContact(raw,1),0);updated.Apply(zone,DerbyDamageState.ScaleContact(raw,2),0);if(Mathf.Abs(updated.Structure-baseline.Structure*2)>.00001f||Mathf.Abs(updated.Engine-baseline.Engine*2)>.00001f||Mathf.Abs(updated.wheels[0]-baseline.wheels[0]*2)>.00001f)throw new Exception("Collision-only scale changed relative damage semantics: "+zone);}if(DerbyDamageState.ScaleContact(0,2)!=0||DerbyDamageState.ScaleContact(float.NaN,2)!=0||DerbyDamageState.ScaleContact(.65f,4)>.65001f)throw new Exception("Contact damage safety bounds failed.");var front=new DerbyDamageState();var rear=new DerbyDamageState();front.Apply(DerbyZone.Front,DerbyDamageState.ScaleContact(.1f,2));rear.Apply(DerbyZone.Rear,DerbyDamageState.ScaleContact(.1f,2));if(Mathf.Abs(rear.Structure/front.Structure-.6f)>.0001f)throw new Exception("Rear protection changed.");}
}
}
